import json
from pathlib import Path
P=lambda ru,es:{'ru':ru,'es':es}
def para(title,text,formal,simple):return dict(title=P(*title),text=P(*text),formal=P(*formal),simple=P(*simple))
def example(title,steps,why,result):return dict(title=P(*title),steps=[P(*x) for x in steps],why=[P(*x) for x in why],result=P(*result))
def ex(id,type,q,ans,explanation,hints,opts=None,**kw):
 d=dict(id=id,type=type,question=P(*q),answer=ans,explanation=P(*explanation),hints=[P(*x) for x in hints]);d.update(kw)
 if opts:d['options']=[P(*x) for x in opts]
 return d
def term(id,name,definition,detail,formula,eg,lesson):return dict(id=id,name=P(*name),definition=P(*definition),detail=P(*detail),formula=formula,example=P(*eg),lessonId=lesson)
lessons=[]
lessons.append(dict(id='atoms',group='foundation',additional=True,title=P('Атомы, молекулы и химические формулы','Átomos, moléculas y fórmulas químicas'),summary=P('Научитесь читать язык химии: символы, индексы, связи и состав вещества.','Aprendé a leer el lenguaje de la química: símbolos, subíndices, enlaces y composición.'),goals=[P('Различать атом, элемент и молекулу.','Distinguir átomo, elemento y molécula.'),P('Считать атомы по формуле, включая скобки.','Contar átomos en fórmulas con paréntesis.')],prereqs=P('Достаточно знать сложение и умножение.','Alcanza con conocer suma y multiplicación.'),sourceIds=[],simulation='atom',paragraphs=[
 para(('Из чего состоит вещество','De qué está hecha la materia'),('Вещество имеет массу и занимает пространство. Атом — химическая частица с ядром и электронами. Число протонов в ядре определяет элемент: 6 протонов означают углерод C, 8 — кислород O. В молекуле атомы соединены химическими связями. Вода содержит молекулы H₂O, каждая состоит из двух атомов H и одного O. Не всякое вещество состоит из отдельных молекул: соль NaCl образует ионную решётку.','La materia tiene masa y ocupa espacio. Un átomo tiene núcleo y electrones. La cantidad de protones define el elemento: 6 protones indican carbono C, 8 oxígeno O. En una molécula los átomos se unen por enlaces. Cada molécula H₂O tiene dos átomos H y uno O. No toda sustancia tiene moléculas separadas: NaCl forma una red iónica.'),('Химический элемент определяется атомным номером Z. Молекула — электрически нейтральная совокупность связанных атомов. Формула NaCl выражает отношение ионов 1:1 в кристалле, а не отдельную молекулу.','El elemento está definido por el número atómico Z. Una molécula es un conjunto eléctricamente neutro de átomos enlazados. NaCl expresa una relación iónica 1:1 en el cristal, no una molécula aislada.'),('Атомы можно представить как детали конструктора, молекулы — как собранные фигуры. Но атомы не твёрдые шарики: связь зависит от электронов, а не от механического замка.','Podés imaginar átomos como piezas y moléculas como figuras armadas. Pero no son bolas rígidas: los enlaces dependen de electrones, no de trabas mecánicas.')),
 para(('Как читать формулу','Cómo leer una fórmula'),('Буква с заглавным началом — символ элемента. C и Ca — разные элементы; CO содержит C и O, а Co обозначает кобальт. Маленькое число справа — индекс, количество атомов этого элемента в одной формульной единице. Если числа нет, оно равно 1. В C₆H₁₂O₆: 6 C, 12 H и 6 O, всего 24 атома. Индекс после скобки умножает всё внутри: Ca(OH)₂ содержит Ca:1, O:2, H:2.','La mayúscula inicia un símbolo. C y Ca son elementos distintos; CO tiene C y O, mientras Co es cobalto. El subíndice indica cantidad de átomos en una unidad. Sin número significa 1. C₆H₁₂O₆ tiene 6 C, 12 H y 6 O: 24 átomos. El subíndice tras paréntesis multiplica todo el grupo: Ca(OH)₂ contiene Ca:1, O:2, H:2.'),('Молекулярная формула задаёт состав, но не порядок связей. Глюкоза и фруктоза имеют одну формулу C₆H₁₂O₆ и различное строение.','La fórmula molecular indica composición, no conectividad. Glucosa y fructosa comparten C₆H₁₂O₆ pero tienen distinta estructura.'),('Читайте C₆ как «шесть атомов углерода», а не «шесть молекул». Число перед всей формулой, например 3H₂O, означает три молекулы.','Leé C₆ como seis átomos de carbono, no seis moléculas. Un número delante de toda la fórmula, como 3H₂O, representa tres moléculas.')),
 para(('Связи и модели','Enlaces y modelos'),('Углерод в обычных нейтральных органических соединениях образует четыре связи по сумме порядков: четыре одинарные или две одинарные и одну двойную. Водород обычно образует одну связь, кислород — две. Схема с шариками помогает считать и сравнивать, но не передаёт реальное распределение электронов и размеры атомов.','En compuestos orgánicos neutros habituales, el carbono suma cuatro unidades de orden de enlace: cuatro simples o dos simples y un doble. El hidrógeno suele formar uno y oxígeno dos. Una representación de bolas ayuda a contar, pero no muestra la distribución electrónica ni tamaños reales.'),('Ковалентная связь связана с общей электронной плотностью между ядрами. Валентность и степень окисления — разные понятия; правило четырёх для C здесь относится к выбранному классу молекул.','Un enlace covalente implica densidad electrónica compartida entre núcleos. Valencia y número de oxidación son distintos; la regla de cuatro para C se limita aquí a la clase estudiada.'),('У C четыре доступных «места» связи: двойная занимает два. Это счётная аналогия; у атома нет четырёх физических отверстий.','C tiene cuatro lugares contables: un doble ocupa dos. Es una analogía de conteo, no cuatro agujeros físicos.'))],formulas=[dict(tex=r'\mathrm{Ca(OH)_2}:\quad N_{Ca}=1,\ N_O=2,\ N_H=2',symbols=P('N — число атомов выбранного элемента в формульной единице.','N es cantidad de átomos del elemento en una unidad.'))],examples=[example(('Посчитаем атомы в 2H₂O','Contemos átomos en 2H₂O'),[('Запишем формулу одной молекулы: H₂O.','Escribimos una molécula: H₂O.'),('Индекс H равен 2, индекс O равен 1.','H tiene subíndice 2 y O tiene 1.'),('Коэффициент 2 умножает число каждого атома.','El coeficiente 2 multiplica cada cantidad.'),('H: 2 × 2 = 4; O: 2 × 1 = 2.','H: 2 × 2 = 4; O: 2 × 1 = 2.'),('Всего 4 + 2 = 6 атомов в двух молекулах.','Hay 4 + 2 = 6 átomos en dos moléculas.')],[('Сначала различим молекулу и набор молекул.','Primero distinguimos una molécula del conjunto.'),('Отсутствующий индекс означает один.','Sin subíndice significa uno.'),('Коэффициент относится ко всей формуле.','El coeficiente afecta toda la fórmula.'),('Считаем элементы отдельно.','Contamos cada elemento por separado.'),('Сумма проверяет общее число.','La suma verifica el total.')],('Ответ: 4 H и 2 O.','Respuesta: 4 H y 2 O.')),example(('Скобки: Ca(OH)₂','Paréntesis: Ca(OH)₂'),[('Снаружи скобок стоит один Ca.','Fuera de paréntesis hay un Ca.'),('В группе OH один O и один H.','OH tiene un O y un H.'),('Индекс 2 повторяет группу дважды.','El 2 repite el grupo dos veces.'),('Получаем O:2 и H:2.','Resultan O:2 y H:2.'),('Сумма атомов 1 + 2 + 2 = 5.','Total: 1 + 2 + 2 = 5.')],[('Индекс скобки не относится к Ca.','El subíndice del grupo no afecta Ca.'),('У каждого символа без индекса количество 1.','Cada símbolo sin índice vale 1.'),('Умножается весь состав группы.','Se multiplica todo el grupo.'),('Не складываем индексы, а умножаем.','Multiplicamos, no sumamos subíndices.'),('Это состав формульной единицы ионного вещества.','Es la composición de una unidad de sustancia iónica.')],('В Ca(OH)₂ пять атомов на формульную единицу.','Ca(OH)₂ tiene cinco átomos por unidad.'))],exercises=[
 ex('atoms-count','numeric',('Сколько атомов всего в одной молекуле C₆H₁₂O₆?','¿Cuántos átomos hay en una molécula C₆H₁₂O₆?'),24,('Сложите 6 + 12 + 6. Индексы считаются для одной молекулы, а не для отдельных порций.','Sumá 6 + 12 + 6. Los subíndices describen una molécula, no porciones.'),[('Посчитайте элементы по отдельности.','Contá cada elemento.'),('Сложите три индекса.','Sumá los tres subíndices.')],tolerance=0),
 ex('atoms-formula','formula',('Введите формулу воды: два H и один O.','Escribí la fórmula del agua: dos H y un O.'),'H2O',('Индекс 2 относится только к H. HO₂ означало бы другой состав.','El subíndice 2 afecta H. HO₂ indica otra composición.'),[('Начните с символа H.','Comenzá por H.'),('Число 1 не пишется.','El número 1 se omite.')]),
 ex('atoms-multi','multi',('Выберите верные утверждения.','Elegí las afirmaciones correctas.'),[0,2],('Коэффициент умножает всю формулу, а индекс меняет состав единицы. NaCl в кристалле не состоит из отдельных молекул.','El coeficiente multiplica toda la fórmula; el subíndice cambia la unidad. NaCl cristalino no tiene moléculas aisladas.'),[('Различите число перед формулой и внутри неё.','Distinguí número delante y dentro.'),('Подумайте об ионной решётке.','Pensá en la red iónica.')],[('2H₂O содержит 4 H.','2H₂O contiene 4 H.'),('NaCl всегда отдельная молекула.','NaCl siempre es una molécula separada.'),('CO и Co обозначают разное.','CO y Co representan cosas distintas.'),('Изменение индекса сохраняет вещество.','Cambiar un subíndice conserva la sustancia.')]),
 ex('atoms-error','error',('Ученик считает в Ca(OH)₂ только один O. Как исправить ошибку?','Un estudiante cuenta un solo O en Ca(OH)₂. ¿Cómo corregirlo?'),1,('Индекс после скобки умножает и O, и H на два. Ca находится вне скобок.','El subíndice tras paréntesis multiplica O y H por dos; Ca queda fuera.'),[('Посмотрите, какие символы находятся внутри скобок.','Mirá los símbolos dentro de paréntesis.'),('Повторите всю группу OH дважды.','Repetí todo OH dos veces.')],[('Умножить только H.','Multiplicar solo H.'),('Умножить O и H на 2.','Multiplicar O y H por 2.'),('Умножить Ca на 2.','Multiplicar Ca por 2.')])],terms=[term('atom',('Атом','Átomo'),('Частица элемента с ядром и электронами.','Partícula de un elemento con núcleo y electrones.'),('Число протонов определяет элемент; число нейтронов может различаться у изотопов.','La cantidad de protones define el elemento; los isótopos varían en neutrones.'),'Z=N_p',('У углерода 6 протонов.','El carbono tiene 6 protones.'),'atoms'),term('molecule',('Молекула','Molécula'),('Связанный нейтральный набор атомов.','Conjunto neutro de átomos enlazados.'),('Молекулярная формула показывает состав; структурная показывает соединение атомов.','La fórmula molecular da composición; la estructural muestra conectividad.'),r'\mathrm{H_2O}',('Вода: 2 H и 1 O.','Agua: 2 H y 1 O.'),'atoms')],notes=[]))
def calcLesson(id,title,summary,prereqs,paras,formulas,examples,exercises,terms,simulation):
 return dict(id=id,group='foundation',additional=True,title=P(*title),summary=P(*summary),goals=[P('Понимать каждое обозначение и проверять единицы.','Entender cada símbolo y verificar unidades.'),P('Решать задачи по шагам и объяснять выбор формулы.','Resolver por pasos y explicar la elección de fórmula.')],prereqs=P(*prereqs),sourceIds=[],paragraphs=paras,formulas=[dict(tex=tex,symbols=P(*s)) for tex,s in formulas],examples=examples,exercises=exercises,terms=terms,simulation=simulation,notes=[P('Подготовительный материал добавлен для понимания школьных листов. Примеры разработаны для курса.','Material preparatorio agregado para comprender las fichas. Ejemplos creados para el curso.')])
def calculation(title,steps,result):
 why=[]
 for ru,es in steps:
  if ru.startswith('Дано'):
   why.append(('Выделяем числовые данные и единицы: это предотвращает использование массы или объёма не того вещества.','Identificamos datos y unidades para no usar la masa o volumen de otra sustancia.'))
  elif ru.startswith('M='):
   why.append(('Каждый индекс показывает число атомов. Сумма их атомных масс даёт массу одного моля молекул.','Cada subíndice cuenta átomos. Sumar sus masas da la masa por mol de moléculas.'))
  elif ru.startswith('Ищем'):
   why.append(('Выбираем формулу по искомой величине: масса делится на массу одного моля, чтобы получить число молей.','Elegimos la fórmula por la incógnita: masa dividida por masa molar da mol.'))
  elif ru.startswith('V='):
   why.append(('В знаменателе концентрации нужны литры. Один литр содержит тысячу миллилитров.','La concentración usa litros; un litro contiene mil mililitros.'))
  elif ru.startswith('n='):
   why.append(('Деление массы на g/mol даёт mol; это число химических порций данной массы.','Dividir g entre g/mol da mol: cantidad de porciones de esa masa.'))
  elif ru.startswith('c=') or ru.startswith('c₂='):
   why.append(('Количество относится к объёму всей смеси; деление на L выражает количество в одном литре.','Usamos volumen total; dividir por L expresa cantidad por litro.'))
  elif ru.startswith('m='):
   why.append(('Умножение mol на g/mol даёт g, а не mol²: единицы количества сокращаются.','Multiplicar mol por g/mol da g; se cancela la unidad mol.'))
  elif 'Провер' in ru or 'Единиц' in ru or 'Объём вырос' in ru:
   why.append(('Обратный расчёт и оценка масштаба позволяют обнаружить ошибку в формуле или переводе единиц.','El cálculo inverso y estimar tamaño detectan errores de fórmula o unidades.'))
  elif 'Из ' in ru or 'получаем' in ru:
   why.append(('Преобразуем равенство одинаковым действием с обеих сторон, сохраняя его смысл.','Aplicamos la misma operación a ambos lados para conservar la igualdad.'))
  elif 'Считаем' in ru or 'совпадает' in ru:
   why.append(('Сохранение атомов проверяется отдельно для каждого элемента, а не только по общей сумме.','Verificamos átomos de cada elemento, no solo el total.'))
  elif 'Поставим' in ru or 'ставим' in ru:
   why.append(('Коэффициент умножает всю молекулу; индекс оставляем неизменным, чтобы не создать другое вещество.','El coeficiente multiplica la molécula; mantenemos subíndices para no cambiar la sustancia.'))
  else:
   why.append(('Опираемся на определение величины и сохранение вещества; каждый символ относится к заданной системе.','Usamos la definición y conservación de materia; cada símbolo corresponde al sistema indicado.'))
 return example(title,steps,why,result)
lessons.append(calcLesson('mole',('Моль и молярная масса','Mol y masa molar'),('Свяжем невидимые частицы с массой, которую можно измерить.','Relacionamos partículas invisibles con masa medible.'),('Прочитайте урок об атомах и формулах.','Leé la lección de átomos y fórmulas.'),[
 para(('Зачем нужен моль','Para qué sirve el mol'),('Химические реакции зависят от количества частиц, а весы измеряют массу. Моль связывает эти два описания. Это единица количества вещества, подобно дюжине как единице счёта, но 1 моль содержит 6,02214076 × 10²³ указанных частиц. Нужно назвать частицы: молекулы воды, атомы C или ионы Na⁺. Один моль воды и один моль углерода содержат одинаковое число указанных частиц, но имеют разную массу.','Las reacciones dependen del número de partículas, pero la balanza mide masa. El mol conecta ambas descripciones. Es unidad de cantidad de sustancia, como una docena cuenta objetos, pero un mol tiene 6,02214076 × 10²³ entidades indicadas. Hay que especificarlas: moléculas de agua, átomos C o iones Na⁺. Un mol de agua y de carbono tiene igual número de entidades, pero distinta masa.'),('Число Авогадро Nₐ = 6,02214076×10²³ моль⁻¹ точно. Количество вещества n = N/Nₐ, где N — число указанных элементарных объектов.','La constante de Avogadro Nₐ = 6,02214076×10²³ mol⁻¹ es exacta. n=N/Nₐ, con N número de entidades especificadas.'),('Дюжина яблок и дюжина монет — по 12 штук, но разный вес. Моль работает как огромная «дюжина». Аналогия касается только счёта.','Una docena de manzanas y de monedas son 12 objetos de distinta masa. El mol es un paquete enorme para contar. La analogía vale solo para el conteo.')),
 para(('Молярная масса как мост','Masa molar como puente'),('Молярная масса M — масса одного моля, обычно в g/mol. Для воды сложим 2 × 1,008 для H и 15,999 для O: M(H₂O)=18,015 g/mol. Числа берутся из таблицы относительных атомных масс, здесь округлённой для школьных расчётов. Если m=36,03 g воды, то число молей n=m/M=2,000 mol. Деление показывает, сколько порций по 18,015 g содержится в данной массе.','La masa molar M es masa por mol, normalmente g/mol. Para agua: 2 × 1,008 de H + 15,999 de O =18,015 g/mol. Se usan masas atómicas promedio redondeadas. Con m=36,03 g, n=m/M=2,000 mol. Dividir cuenta cuántas porciones de 18,015 g caben en esa masa.'),('M=m/n. Для чистого вещества m=nM. Единица: mol × g/mol = g. Массу раствора нельзя считать массой растворённого вещества без сведений о составе.','M=m/n. Para sustancia pura m=nM. Unidad: mol × g/mol = g. La masa de solución no equivale a masa de soluto sin conocer composición.'),('M — масса одной химической порции. Делим общую массу на массу порции. Не путайте mol и g: это разные величины.','M es la masa de una porción química. Dividimos masa total por masa de porción. Mol y g representan magnitudes distintas.')),
 para(('Проверка расчёта','Verificar el cálculo'),('Запишите массу в g, M в g/mol и только затем делите. Если масса дана в mg, сначала разделите её на 1000. Результат можно проверить обратным действием: n × M должно вернуть исходную m. Значение N получается умножением n на Nₐ и относится к тому типу частиц, который указан в условии.','Escribí masa en g y M en g/mol antes de dividir. Para mg dividí por 1000. Verificá con n × M: debe recuperar m. N se obtiene con n × Nₐ y cuenta el tipo de partículas indicado.'),('При округлении сохраняем промежуточные цифры и округляем итог. Школьные таблицы могут использовать H=1, C=12, O=16; тогда ответы отличаются в пределах точности.','Conservá cifras intermedias y redondeá el resultado. Tablas escolares pueden usar H=1, C=12, O=16; las diferencias reflejan la precisión.'),('Если половина массы одной порции, количество должно быть 0,5 mol. Проверка размером результата помогает заметить ошибку ×1000.','Media masa de una porción debe dar 0,5 mol. Estimar el tamaño ayuda a detectar errores por un factor de 1000.'))],[(r'n=\frac{m}{M},\quad m=nM,\quad N=nN_A',('n — mol; m — g; M — g/mol; N — число частиц.','n en mol; m en g; M en g/mol; N cantidad de partículas.'))], [calculation(('Количество вещества глюкозы','Cantidad de glucosa'),[('Дано m=18,016 g, формула C₆H₁₂O₆.','Datos: m=18,016 g, fórmula C₆H₁₂O₆.'),('Ищем n в mol, поэтому используем n=m/M.','Buscamos n en mol; usamos n=m/M.'),('M=6×12,011+12×1,008+6×15,999=180,156 g/mol.','M=6×12,011+12×1,008+6×15,999=180,156 g/mol.'),('n=18,016/180,156≈0,1000 mol.','n=18,016/180,156≈0,1000 mol.'),('Проверка: 0,1000×180,156≈18,016 g.','Verificación: 0,1000×180,156≈18,016 g.')],('Ответ: около 0,1000 mol.','Respuesta: aproximadamente 0,1000 mol.')),calculation(('Масса 0,5 mol воды','Masa de 0,5 mol de agua'),[('Дано n=0,5 mol и H₂O.','Datos: n=0,5 mol y H₂O.'),('M=2×1,008+15,999=18,015 g/mol.','M=2×1,008+15,999=18,015 g/mol.'),('Из n=m/M получаем m=nM.','De n=m/M se obtiene m=nM.'),('m=0,5×18,015=9,0075 g.','m=0,5×18,015=9,0075 g.'),('Единицы mol×g/mol=g. Это половина массы одного моля.','mol×g/mol=g. Es la mitad de la masa de un mol.')],('Ответ: около 9,01 g.','Respuesta: alrededor de 9,01 g.'))], [ex('mole-mass','numeric',('Найдите M(CO₂), используя C=12,011 и O=15,999.','Calculá M(CO₂) con C=12,011 y O=15,999.'),44.009,('Сумма 12,011 + 2×15,999 = 44,009 g/mol.','12,011 + 2×15,999 = 44,009 g/mol.'),[('Кислородов два.','Hay dos oxígenos.'),('Умножьте массу O на индекс.','Multiplicá masa de O por su índice.')],unit='g/mol',tolerance=.05),ex('mole-amount','numeric',('36,03 g чистой воды: сколько mol? M=18,015 g/mol.','36,03 g de agua pura: ¿cuántos mol? M=18,015 g/mol.'),2,('n=m/M=36,03/18,015=2 mol.','n=m/M=36,03/18,015=2 mol.'),[('Массу нужно делить на молярную массу.','Dividí la masa por M.'),('Проверьте обратным умножением.','Verificá multiplicando.')],unit='mol'),ex('mole-order','order',('Расположите действия плана: сначала формула и M, затем единицы массы и расчёт n.','Ordená este plan: primero fórmula y M, luego unidades de masa y cálculo de n.'),[1,3,0,2],('Сначала читаем формулу, затем считаем M, переводим массу в g и делим. Перевод единиц можно сделать раньше M, но здесь выбран такой план.','Leemos fórmula, calculamos M, expresamos masa en g y dividimos. Convertir antes de M también es válido; aquí ordenamos este plan.'),[('Формула нужна для M.','La fórmula permite hallar M.'),('Деление — последний этап.','La división va al final.')],[('Записать массу в g.','Escribir masa en g.'),('Прочитать химическую формулу.','Leer fórmula química.'),('Вычислить n=m/M.','Calcular n=m/M.'),('Вычислить M по формуле.','Calcular M con la fórmula.')]),ex('mole-steps','steps',('Решите задачу по шагам: 9,0075 g H₂O. Введите M, затем n.','Resolvé por pasos: 9,0075 g H₂O. Ingresá M y luego n.'),['18.015','0.5'],('M=18,015 g/mol, n=9,0075/18,015=0,5 mol.','M=18,015 g/mol; n=9,0075/18,015=0,5 mol.'),[('M=2M(H)+M(O).','M=2M(H)+M(O).'),('n=m/M.','n=m/M.')],[('M (g/mol)','M (g/mol)'),('n (mol)','n (mol)')])],[term('mole',('Моль','Mol'),('Единица количества вещества; 6,02214076×10²³ указанных частиц.','Unidad de cantidad de sustancia; 6,02214076×10²³ entidades especificadas.'),('Называйте частицы: атомы, молекулы, ионы. Масса моля зависит от вещества.','Indicá si son átomos, moléculas o iones. La masa de un mol depende de la sustancia.'),'N=nN_A',('1 mol H₂O содержит число Авогадро молекул.','1 mol H₂O contiene el número de Avogadro de moléculas.'),'mole'),term('molar-mass',('Молярная масса','Masa molar'),('Масса вещества на один моль.','Masa de sustancia por mol.'),('Вычисляется суммой атомных масс с учётом индексов. Единица g/mol.','Se suma masa atómica por cada subíndice. Unidad g/mol.'),'M=m/n',('M(H₂O)=18,015 g/mol.','M(H₂O)=18,015 g/mol.'),'mole')],'mole'))
lessons.append(calcLesson('concentration',('Растворы, концентрация и единицы','Soluciones, concentración y unidades'),('Почему одинаковый стакан может содержать разное количество вещества.','Por qué un mismo vaso puede contener diferente cantidad de sustancia.'),('Понимать моль, массу и деление.','Entender mol, masa y división.'),[
 para(('Что такое раствор','Qué es una solución'),('Раствор — однородная смесь. Растворитель задаёт среду, растворённое вещество распределено в ней. В водном растворе сахара вода — растворитель. Объём раствора измеряют после растворения: он не всегда равен сумме исходных объёмов. Концентрация отвечает на вопрос, сколько выбранного вещества содержится в определённой порции раствора.','Una solución es una mezcla homogénea. El solvente constituye el medio y el soluto se distribuye en él. En azúcar acuosa, agua es solvente. Medimos el volumen final, que no siempre es la suma inicial. La concentración indica cuánto soluto hay en una porción de solución.'),('Раствор однороден на молекулярном или ионном уровне. Концентрации массовая, молярная и массовая доля имеют разные размерности.','La solución es homogénea a nivel molecular o iónico. Concentración másica, molar y fracción másica tienen dimensiones distintas.'),('Чай с одной ложкой сахара и с тремя имеет разную концентрацию. Но ложка — неточная мера: в расчёте нужны g, mol и объём.','Té con una cucharada o tres tiene distinta concentración. La cuchara es imprecisa: el cálculo requiere g, mol y volumen.')),
 para(('Молярная концентрация','Concentración molar'),('c=n/V, где n — mol растворённого вещества, V — L всего раствора. Если 0,10 mol сахара содержится в 0,50 L раствора, c=0,20 mol/L. Это не означает, что стакан содержит 0,20 mol: столько было бы в целом литре того же раствора. Для перевода 250 mL в L делим на 1000 и получаем 0,250 L.','c=n/V: n en mol de soluto, V en L de solución. Si 0,10 mol están en 0,50 L, c=0,20 mol/L. No significa 0,20 mol en ese vaso: sería la cantidad en un litro de esa solución. 250 mL/1000=0,250 L.'),('Молярная концентрация вещества зависит от объёма и температуры. При реакции или диссоциации концентрация отдельных частиц может отличаться от аналитической c₀.','La concentración molar depende de volumen y temperatura. Tras reacción o disociación, las concentraciones de especies difieren de la concentración analítica c₀.'),('Концентрация похожа на число людей на квадратный метр: она связывает количество с размером места. Здесь размер — объём, а количество — mol.','Como personas por metro cuadrado relaciona cantidad y espacio, c relaciona mol y volumen. La analogía no describe interacciones químicas.')),
 para(('Разбавление и массовая доля','Dilución y fracción másica'),('Если добавить только растворитель и вещество не реагирует, число молей сохраняется: c₁V₁=c₂V₂. V₂ — конечный объём, не объём добавленной воды. Массовая доля w=m(вещества)/m(раствора); в процентах умножаем на 100. Нельзя подставлять массу растворителя в знаменатель.','Si agregás solo solvente sin reacción, se conserva n: c₁V₁=c₂V₂. V₂ es volumen final, no agua agregada. Fracción másica w=m(soluto)/m(solución); para porcentaje multiplicamos por 100. El denominador no es masa de solvente.'),('Разбавление следует из сохранения количества вещества. w безразмерна, c имеет единицу mol/L. 10 % m/m означает 10 g soluto в 100 g solución.','Diluir conserva cantidad de sustancia. w es adimensional; c tiene unidad mol/L. 10 % m/m significa 10 g soluto por 100 g solución.'),('Добавленная вода распределяет то же вещество в большем объёме. Сахар не исчезает: его порция на литр уменьшается.','Más agua reparte el mismo soluto en más volumen. No desaparece azúcar; baja la cantidad por litro.'))],[(r'c=\frac{n}{V}=\frac{m}{MV},\qquad c_1V_1=c_2V_2',('c — mol/L; V — L; m — g растворённого вещества; M — g/mol.','c en mol/L; V en L; m en g de soluto; M en g/mol.'))], [calculation(('Раствор глюкозы','Solución de glucosa'),[('Дано 18,0156 g глюкозы в 500 mL раствора.','18,0156 g de glucosa en 500 mL de solución.'),('M=180,156 g/mol; n=18,0156/180,156=0,100 mol.','M=180,156 g/mol; n=0,100 mol.'),('V=500/1000=0,500 L.','V=500/1000=0,500 L.'),('c=n/V=0,100/0,500=0,200 mol/L.','c=n/V=0,100/0,500=0,200 mol/L.'),('Проверка: cV=0,200×0,500=0,100 mol.','Verificación: cV=0,100 mol.')],('Ответ: 0,200 mol/L.','Respuesta: 0,200 mol/L.')),calculation(('Разбавление','Dilución'),[('Дано c₁=1,0 mol/L, V₁=0,10 L, V₂=0,50 L.','c₁=1,0 mol/L, V₁=0,10 L, V₂=0,50 L.'),('Без реакции n₁=n₂.','Sin reacción n₁=n₂.'),('Из c₁V₁=c₂V₂ получаем c₂=c₁V₁/V₂.','c₂=c₁V₁/V₂.'),('c₂=1,0×0,10/0,50=0,20 mol/L.','c₂=1,0×0,10/0,50=0,20 mol/L.'),('Объём вырос в 5 раз, концентрация упала в 5 раз.','Volumen aumentó cinco veces; concentración bajó cinco veces.')],('Ответ: 0,20 mol/L.','Respuesta: 0,20 mol/L.'))], [ex('conc-number','numeric',('0,05 mol в 250 mL раствора. Найдите c.','0,05 mol en 250 mL de solución. Hallá c.'),.2,('250 mL=0,250 L, c=0,05/0,250=0,20 mol/L.','250 mL=0,250 L; c=0,05/0,250=0,20 mol/L.'),[('Переведите mL в L.','Convertí mL en L.'),('Разделите n на V.','Dividí n por V.')],unit='mol/L'),ex('conc-percent','numeric',('10 g сахара и 90 g воды: массовая доля сахара в процентах?','10 g de azúcar y 90 g de agua: ¿porcentaje másico de azúcar?'),10,('Масса раствора 100 g, 10/100×100%=10%.','La solución pesa 100 g: 10/100×100%=10%.'),[('Сложите массы.','Sumá ambas masas.'),('Делите на массу всего раствора.','Dividí por masa de solución.')],unit='%'),ex('conc-choice','choice',('При разбавлении без реакции сохраняется…','Al diluir sin reacción se conserva…'),1,('Добавляем растворитель; n вещества сохраняется, V растёт и c меняется.','Se agrega solvente; n se conserva, V aumenta y c cambia.'),[('Какие частицы добавляются?','¿Qué partículas agregás?'),('Само растворённое вещество не удаляется.','El soluto no se elimina.')],[('Концентрация.','Concentración.'),('Количество растворённого вещества.','Cantidad de soluto.'),('Объём.','Volumen.')]),ex('conc-match','match',('Сопоставьте величины и единицы.','Relacioná magnitudes y unidades.'),[0,1,2],('Масса m измеряется в g, количество n в mol, c в mol/L.','m se mide en g, n en mol y c en mol/L.'),[('n считает химические порции.','n cuenta porciones químicas.'),('c — количество на объём.','c es cantidad por volumen.')],[('Масса m','Masa m'),('Количество n','Cantidad n'),('Концентрация c','Concentración c')],matches=[P('Грамм (g)','Gramo (g)'),P('Моль (mol)','Mol (mol)'),P('Моль на литр (mol/L)','Mol por litro (mol/L)')])],[term('concentration',('Молярная концентрация','Concentración molar'),('Количество растворённого вещества в единице объёма раствора.','Cantidad de soluto por volumen de solución.'),('Используйте конечный объём всего раствора, обычно L.','Usá el volumen final total, normalmente L.'),'c=n/V',('0,1 mol в 0,5 L даёт 0,2 mol/L.','0,1 mol en 0,5 L da 0,2 mol/L.'),'concentration')],'dilution'))
lessons.append(calcLesson('equations',('Уравнения реакций и сохранение атомов','Ecuaciones y conservación de átomos'),('Балансировка как честный учёт каждого атома.','Balancear es contar cada átomo.'),('Уметь читать формулы и считать атомы.','Saber leer fórmulas y contar átomos.'),[
 para(('Что означает стрелка','Qué significa la flecha'),('Слева записаны реагенты, справа продукты. Реакция перестраивает связи, но в обычной химии не превращает один элемент в другой. Поэтому число атомов каждого элемента должно совпадать слева и справа. В ионном уравнении дополнительно сохраняется суммарный заряд.','A la izquierda están reactivos y a la derecha productos. Una reacción reorganiza enlaces, pero no cambia un elemento en otro en química habitual. Debe coincidir la cantidad de cada elemento a ambos lados; en ecuaciones iónicas también la carga.'),('Баланс атомов и электрического заряда — обязательные условия корректного уравнения; они не доказывают, что реакция самопроизвольна или быстра.','Conservar átomos y carga es necesario; no demuestra que la reacción sea espontánea ni rápida.'),('Можно перестроить фигуру из деталей, сохранив все детали. Но химическая возможность зависит ещё и от энергии и условий.','Podés reorganizar piezas sin perderlas. La posibilidad química depende también de energía y condiciones.')),
 para(('Коэффициенты и индексы','Coeficientes y subíndices'),('В H₂ + O₂ → H₂O кислород не совпадает: 2 слева и 1 справа. Поставим 2 перед H₂O, тогда справа 4 H. Теперь поставим 2 перед H₂. Получаем 2H₂ + O₂ → 2H₂O. Коэффициент умножает всю формулу. Изменить H₂O на H₂O₂ нельзя: перекись водорода — другое вещество.','H₂ + O₂ → H₂O no balancea O: 2 a la izquierda, 1 a la derecha. Ponemos 2H₂O: quedan 4 H. Ponemos 2H₂ a la izquierda. Resulta 2H₂ + O₂ → 2H₂O. El coeficiente multiplica toda la fórmula. Cambiar a H₂O₂ crearía peróxido, otra sustancia.'),('Стехиометрические коэффициенты выражают отношения количеств вещества. Любое общее положительное кратное сохраняет баланс; принято приводить к минимальным целым.','Los coeficientes estequiométricos expresan relaciones de cantidades. Todo múltiplo común positivo conserva balance; se usan enteros mínimos.'),('Индекс — состав одной порции; коэффициент — сколько таких порций берём.','Subíndice es composición de una porción; coeficiente indica cuántas porciones.')),
 para(('Как использовать пропорцию','Cómo usar la proporción'),('Уравнение гидролиза сахарозы C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆ показывает 1 mol сахарозы на 1 mol воды и по 1 mol глюкозы и фруктозы. Массы продуктов не равны массам реагентов по отдельности, но общая масса сохраняется в закрытой системе. Коэффициенты задают mol, а не g.','La hidrólisis de sacarosa C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆ usa 1 mol de sacarosa y de agua, y produce 1 mol de glucosa y de fructosa. Las masas individuales difieren, pero la masa total se conserva en sistema cerrado. Los coeficientes relacionan mol, no g.'),('nᵢ/νᵢ — стехиометрическое отношение для полного превращения при отсутствии побочных реакций. Лимитирующий реагент определяется минимальным nᵢ/νᵢ.','nᵢ/νᵢ describe proporción estequiométrica sin reacciones laterales. El reactivo limitante tiene menor nᵢ/νᵢ.'),('Рецепт 2 порции H₂ на 1 порцию O₂ означает число частиц, а не одинаковые массы.','Una receta 2 porciones H₂ por 1 O₂ habla de entidades, no de masas iguales.'))],[(r'2\mathrm{H_2}+\mathrm{O_2}\rightarrow2\mathrm{H_2O}',('H: 4 с каждой стороны, O: 2 с каждой стороны.','H: 4 por lado; O: 2 por lado.'))], [calculation(('Баланс образования воды','Balance de formación de agua'),[('Запишем H₂ + O₂ → H₂O.','Escribimos H₂ + O₂ → H₂O.'),('Считаем O: слева 2, справа 1.','Contamos O: 2 izquierda y 1 derecha.'),('Поставим 2 перед H₂O, справа O:2 и H:4.','Ponemos 2H₂O: O:2 y H:4.'),('Поставим 2 перед H₂, слева H:4.','Ponemos 2H₂: H:4 a izquierda.'),('Проверяем оба элемента: H 4=4, O 2=2.','Verificamos H 4=4 y O 2=2.')],('2H₂ + O₂ → 2H₂O.','2H₂ + O₂ → 2H₂O.')),calculation(('Сгорание метана','Combustión del metano'),[('CH₄ + O₂ → CO₂ + H₂O.','CH₄ + O₂ → CO₂ + H₂O.'),('C совпадает, 1 с обеих сторон.','C coincide: 1 por lado.'),('H слева 4, ставим 2 перед H₂O.','H izquierda 4: ponemos 2H₂O.'),('O справа 2+2=4, ставим 2 перед O₂.','O derecha 2+2=4: ponemos 2O₂.'),('Проверяем C:1, H:4, O:4 на каждой стороне.','Verificamos C:1, H:4, O:4 por lado.')],('CH₄ + 2O₂ → CO₂ + 2H₂O.','CH₄ + 2O₂ → CO₂ + 2H₂O.'))], [ex('eq-balance','balance',('Уравняйте CH₄ + O₂ → CO₂ + H₂O.','Balanceá CH₄ + O₂ → CO₂ + H₂O.'),[1,2,1,2],('C задаёт 1 CO₂, H задаёт 2 H₂O, значит справа 4 O и нужно 2 O₂.','C exige 1 CO₂ y H exige 2 H₂O: hay 4 O, por eso 2 O₂.'),[('Начните с C и H.','Empezá por C y H.'),('Кислород балансируется последним.','Balanceá O al final.')],[('CH₄','CH₄'),('O₂','O₂'),('CO₂','CO₂'),('H₂O','H₂O')]),ex('eq-index','error',('Ученик заменил H₂O на H₂O₂, чтобы уравнять кислород. В чём ошибка?','Un estudiante cambió H₂O por H₂O₂ para balancear O. ¿Cuál es el error?'),0,('Индексы определяют вещество. Балансируем только коэффициентами.','Los subíndices definen sustancia. Balanceamos con coeficientes.'),[('Сравните состав воды и перекиси.','Compará agua y peróxido.'),('Какое число можно менять перед формулой?','¿Qué número podés cambiar delante?')],[('Изменился продукт реакции.','Cambió el producto.'),('Коэффициенты обязаны быть нулём.','Los coeficientes deben ser cero.'),('Кислород не сохраняется в химии.','El oxígeno no se conserva.')]),ex('eq-proportion','numeric',('Полный гидролиз 0,20 mol сахарозы. Сколько mol глюкозы получается?','Hidrólisis completa de 0,20 mol de sacarosa. ¿Cuántos mol de glucosa?'),.2,('Коэффициенты сахарозы и глюкозы 1:1, поэтому 0,20 mol.','Sacarosa y glucosa están 1:1: 0,20 mol.'),[('Не складывайте глюкозу и фруктозу.','No sumes glucosa y fructosa.'),('У каждого отдельного продукта коэффициент 1.','Cada producto tiene coeficiente 1.')],unit='mol'),ex('eq-multi','multi',('Что обязательно сохраняется в уравнении обычной химической реакции?','¿Qué se conserva necesariamente en una reacción química habitual?'),[0,1],('Сохраняются атомы каждого элемента и общий заряд. Число молекул и объём могут меняться.','Se conservan átomos por elemento y carga total. Moléculas y volumen pueden cambiar.'),[('Молекулы перестраиваются.','Las moléculas se reorganizan.'),('Элементы не превращаются друг в друга.','Los elementos no se transforman entre sí.')],[('Число атомов каждого элемента.','Átomos de cada elemento.'),('Суммарный заряд.','Carga total.'),('Число молекул.','Número de moléculas.'),('Объём.','Volumen.')])],[term('stoichiometry',('Стехиометрия','Estequiometría'),('Количественные отношения веществ в реакции.','Relaciones cuantitativas entre sustancias de una reacción.'),('Коэффициенты уравнения задают отношения mol. Проверяется сохранение атомов и заряда.','Coeficientes indican relaciones de mol. Se verifica conservación de átomos y carga.'),'n_i/\nu_i=n_j/\nu_j',('В 2H₂+O₂→2H₂O отношение H₂:O₂ равно 2:1.','En 2H₂+O₂→2H₂O la relación H₂:O₂ es 2:1.'),'equations')],'balance'))
lessons[0]['sourceIds']=[43,44]
lessons[0]['notes'].append(P('Фотография 43 содержит план курса, 44 — пустую страницу для результатов. Они сохранены как контекст программы и не содержат нерешённой задачи.','La foto 43 contiene el plan del curso y 44 una página vacía de evaluaciones. Se conservan como contexto y no contienen ejercicios pendientes.'))
